def show(cells):
    ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
    for i in range(min(ys),max(ys)+1):
        print(' '.join(str(dict(((p[0],p[1]),p[2]) for p in cells).get((i,j),9)) for j in range(min(xs),max(xs)+1)))
print("stamp:"); show([(i-r0,j-c0,v) for r0,c0 in [(6,7)] for i,j,v in stamp])
# clusters from previous run lost? recompute quickly
seen=set(); clusters=[]
for i in range(21):
    for j in range(10):
        if O[i][j]!=7 and (i,j) not in seen:
            stack=[(i,j)]; comp=[]
            while stack:
                y,x=stack.pop()
                if (y,x) in seen or not(0<=y<21 and 0<=x<10) or O[y][x]==7: continue
                seen.add((y,x)); comp.append((y,x,O[y][x]))
                for d in [(1,0),(-1,0),(0,1),(0,-1)]: stack.append((y+d[0],x+d[1]))
            clusters.append(comp)
for n,c in enumerate(clusters):
    ys=[p[0] for p in c]; xs=[p[1] for p in c]
    print("cluster",n,min(ys),min(xs))
    show([(y-min(ys),x-min(xs),v) for y,x,v in c])

pos=[(i,j) for i,row in enumerate(G) for j,v in enumerate(row) if v==6]
# cluster 6s with 8-connectivity (diagonal) since scattered
seen=set(); comps=[]
for p in pos:
    if p in seen: continue
    stack=[p]; comp=[]
    while stack:
        y,x=stack.pop()
        if (y,x) in seen: continue
        seen.add((y,x)); comp.append((y,x))
        for dy in (-1,0,1):
            for dx in (-1,0,1):
                if (y+dy,x+dx) in pos and (y+dy,x+dx) not in seen: stack.append((y+dy,x+dx))
    comps.append(comp)
for c in sorted(comps, key=lambda c:min(p[0] for p in c)):
    print(sorted(c))

O=[row[:] for row in G]
for i,row in enumerate(G):
